package com.lmspilot.learning.domain; import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="course_progress") public class CourseProgressEntity { @Id public UUID id=UUID.randomUUID(); @Column(nullable=false,unique=true) public UUID enrollmentId; @Column(nullable=false) public UUID courseId; @Column(nullable=false) public UUID userId; @Column(nullable=false) public int courseVersion=1; @Column(nullable=false) public int progressPercent; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) public LearningStatus status=LearningStatus.NOT_STARTED; public Instant startedAt; public Instant completedAt; @Column(nullable=false) public Instant updatedAt=Instant.now(); @Version public long version; public CourseProgressEntity(){} }
